import unicodedata

from django.db import migrations, models

# Palabras (sin tildes, en minuscula) que indican cada servicio.
PALABRAS_POR_SERVICIO = {
    'cubre_consultas': ('consulta', 'control', 'clinica'),
    'cubre_vacunacion': ('vacun',),
    'cubre_guardia': ('guardia', 'urgencia', 'emergencia'),
}


def _normalizar(texto):
    sin_tildes = ''.join(
        caracter
        for caracter in unicodedata.normalize('NFKD', texto or '')
        if not unicodedata.combining(caracter)
    )
    return sin_tildes.lower()


def texto_a_servicios(apps, schema_editor):
    """Interpreta servicio_cubierto. Si un texto no menciona ningun
    servicio conocido, se marcan los tres (y se avisa por consola)."""
    ObraSocial = apps.get_model('administracion', 'ObraSocial')
    sin_interpretar = []
    for obra_social in ObraSocial.objects.all():
        texto = _normalizar(obra_social.servicio_cubierto)
        cubre = {
            campo: any(palabra in texto for palabra in palabras)
            for campo, palabras in PALABRAS_POR_SERVICIO.items()
        }
        if not any(cubre.values()):
            cubre = dict.fromkeys(PALABRAS_POR_SERVICIO, True)
            sin_interpretar.append(
                f'{obra_social.nombre} ("{obra_social.servicio_cubierto}")'
            )
        for campo, valor in cubre.items():
            setattr(obra_social, campo, valor)
        obra_social.save(update_fields=list(cubre))
    if sin_interpretar:
        print(
            '\n  AVISO: no se pudo interpretar servicio_cubierto de: '
            + '; '.join(sin_interpretar)
            + '. Se marcaron los tres servicios; revisalas en el admin.'
        )


def servicios_a_texto(apps, schema_editor):
    ObraSocial = apps.get_model('administracion', 'ObraSocial')
    etiquetas = {
        'cubre_consultas': 'Consultas',
        'cubre_vacunacion': 'Vacunación',
        'cubre_guardia': 'Guardia',
    }
    for obra_social in ObraSocial.objects.all():
        obra_social.servicio_cubierto = ', '.join(
            etiqueta for campo, etiqueta in etiquetas.items()
            if getattr(obra_social, campo)
        )
        obra_social.save(update_fields=['servicio_cubierto'])


